function hitBricks(grid: number[][], hits: number[][]): number[] {
    const m = grid.length;
    const n = grid[0].length;
    const roof = m * n;
    const state = new Uint8Array(roof);

    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            state[r * n + c] = grid[r][c];
        }
    }

    const removed = new Uint8Array(hits.length);
    for (let i = 0; i < hits.length; i++) {
        const id = hits[i][0] * n + hits[i][1];
        if (state[id] === 1) {
            removed[i] = 1;
            state[id] = 0;
        }
    }

    const parent = new Int32Array(roof + 1);
    const size = new Int32Array(roof + 1);
    for (let i = 0; i <= roof; i++) {
        parent[i] = i;
        size[i] = 1;
    }

    function find(x: number): number {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    function union(a: number, b: number): void {
        let rootA = find(a);
        let rootB = find(b);
        if (rootA === rootB) return;

        if (size[rootA] < size[rootB]) {
            const temp = rootA;
            rootA = rootB;
            rootB = temp;
        }

        parent[rootB] = rootA;
        size[rootA] += size[rootB];
    }

    // Build connectivity after all directly hit bricks have been removed.
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            const id = r * n + c;
            if (state[id] === 0) continue;

            if (r === 0) union(id, roof);
            if (r > 0 && state[id - n] === 1) union(id, id - n);
            if (c > 0 && state[id - 1] === 1) union(id, id - 1);
        }
    }

    const result = new Array<number>(hits.length).fill(0);

    // Restoring a brick reconnects exactly the bricks that fell at that hit.
    for (let i = hits.length - 1; i >= 0; i--) {
        if (removed[i] === 0) continue;

        const [r, c] = hits[i];
        const id = r * n + c;
        const before = size[find(roof)];

        state[id] = 1;
        if (r === 0) union(id, roof);
        if (r > 0 && state[id - n] === 1) union(id, id - n);
        if (r + 1 < m && state[id + n] === 1) union(id, id + n);
        if (c > 0 && state[id - 1] === 1) union(id, id - 1);
        if (c + 1 < n && state[id + 1] === 1) union(id, id + 1);

        const after = size[find(roof)];
        result[i] = Math.max(0, after - before - 1);
    }

    return result;
};
