    let result = 0;
    let sign = 1;

    for (let current = n; current > 0; current -= 4) {
        let term = current;

        if (current >= 2) {
            term *= current - 1;
        }
        if (current >= 3) {
            term = Math.floor(term / (current - 2));
        }

        result += sign * term;

        if (current >= 4) {
            result += current - 3;
        }

        sign = -1;
    }

    return result;
};
