function numSmallerByFrequency(queries: string[], words: string[]): number[] {
    function frequency(s: string): number {
        let smallest = 123;
        let count = 0;

        for (let i = 0; i < s.length; i++) {
            const char = s.charCodeAt(i);
            if (char < smallest) {
                smallest = char;
                count = 1;
            } else if (char === smallest) {
                count++;
            }
        }

        return count;
    }

    const suffix: number[] = new Array(12).fill(0);

    for (const word of words) {
        suffix[frequency(word)]++;
    }

    for (let i = 10; i >= 1; i--) {
        suffix[i] += suffix[i + 1];
    }

    return queries.map(query => suffix[frequency(query) + 1]);
};
