function countMaxOrSubsets(nums: number[]): number {
    const n = nums.length;
    let maxOr = 0;

    for (const num of nums) {
        maxOr |= num;
    }

    function dfs(index: number, currentOr: number): number {
        if (currentOr === maxOr) {
            return 2 ** (n - index);
        }

        if (index === n) {
            return 0;
        }

        return dfs(index + 1, currentOr | nums[index]) +
               dfs(index + 1, currentOr);
    }

    return dfs(0, 0);
};
