function countTriples(n: number): number {
    let count = 0;
    const maxSquare = n * n;

    for (let a = 1; a <= n; a++) {
        for (let b = a + 1; b <= n; b++) {
            const sum = a * a + b * b;
            if (sum > maxSquare) break;

            if (Number.isInteger(Math.sqrt(sum))) {
                count += 2;
            }
        }
    }

    return count;
};
