function countVowelSubstrings(word: string): number {
    const vowels = "aeiou";
    const lastSeen: number[] = new Array(5).fill(-1);
    let lastConsonant = -1;
    let count = 0;

    for (let i = 0; i < word.length; i++) {
        const vowelIndex = vowels.indexOf(word[i]);

        if (vowelIndex === -1) {
            lastConsonant = i;
            continue;
        }

        lastSeen[vowelIndex] = i;

        const earliestLastSeen = Math.min(...lastSeen);
        count += Math.max(0, earliestLastSeen - lastConsonant);
    }

    return count;
};
