function canCross(stones: number[]): boolean {
    const n = stones.length;

    for (let i = 1; i < n; i++) {
        if (stones[i] - stones[i - 1] > i) {
            return false;
        }
    }

    // dp[i][k] indicates whether stone i is reachable with a jump of k units.
    const dp = Array.from({ length: n }, () => new Uint8Array(n + 1));
    dp[0][0] = 1;

    for (let i = 1; i < n; i++) {
        for (let j = i - 1; j >= 0; j--) {
            const jump = stones[i] - stones[j];

            // The largest possible outgoing jump from stone j is j + 1.
            if (jump > j + 1) {
                break;
            }

            if (
                dp[j][jump - 1] ||
                dp[j][jump] ||
                dp[j][jump + 1]
            ) {
                dp[i][jump] = 1;

                if (i === n - 1) {
                    return true;
                }
            }
        }
    }

    return false;
};
