    const m = grid.length;
    const n = grid[0].length;

    const rows = Array.from({ length: m }, () => Array(n + 1).fill(0));
    const cols = Array.from({ length: m + 1 }, () => Array(n).fill(0));
    const diagonal = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));
    const antiDiagonal = Array.from(
        { length: m + 1 },
        () => Array(n + 1).fill(0)
    );

    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            const value = grid[r][c];
            rows[r][c + 1] = rows[r][c] + value;
            cols[r + 1][c] = cols[r][c] + value;
            diagonal[r + 1][c + 1] = diagonal[r][c] + value;
            antiDiagonal[r + 1][c] = antiDiagonal[r][c + 1] + value;
        }
    }

    for (let size = Math.min(m, n); size >= 2; size--) {
        for (let r = 0; r + size <= m; r++) {
            for (let c = 0; c + size <= n; c++) {
                const target = rows[r][c + size] - rows[r][c];

                if (
                    diagonal[r + size][c + size] - diagonal[r][c] !== target ||
                    antiDiagonal[r + size][c] - antiDiagonal[r][c + size] !== target
                ) {
                    continue;
