function maxScore(nums: number[]): number {
    const m = nums.length;
    const fullMask = (1 << m) - 1;
    const memo = new Int32Array(1 << m);
    memo.fill(-1);
    memo[fullMask] = 0;

    const gcd = (a: number, b: number): number => {
        while (b !== 0) {
            const remainder = a % b;
            a = b;
            b = remainder;
        }
        return a;
    };

    const pairGcd = Array.from({ length: m }, () => new Int32Array(m));
    for (let i = 0; i < m; i++) {
        for (let j = i + 1; j < m; j++) {
            pairGcd[i][j] = gcd(nums[i], nums[j]);
        }
    }

    const dfs = (mask: number, operation: number): number => {
        if (memo[mask] !== -1) return memo[mask];

        let best = 0;
        for (let i = 0; i < m; i++) {
            if ((mask & (1 << i)) !== 0) continue;

            for (let j = i + 1; j < m; j++) {
                if ((mask & (1 << j)) !== 0) continue;

                const nextMask = mask | (1 << i) | (1 << j);
                const score =
                    operation * pairGcd[i][j] + dfs(nextMask, operation + 1);
                best = Math.max(best, score);
            }
        }

        memo[mask] = best;
        return best;
    };

    return dfs(0, 1);
};
