function maximumANDSum(nums: number[], numSlots: number): number {
    const powers = new Array<number>(numSlots + 1);
    powers[0] = 1;
    for (let i = 1; i <= numSlots; i++) {
        powers[i] = powers[i - 1] * 3;
    }

    // Each ternary digit records a slot's occupancy: 0, 1, or 2.
    const memo = new Int32Array(powers[numSlots]);
    memo.fill(-1);

    function dfs(state: number, index: number): number {
        if (index === nums.length) return 0;
        if (memo[state] !== -1) return memo[state];

        let best = 0;
        for (let slot = 0; slot < numSlots; slot++) {
            const occupancy = Math.floor(state / powers[slot]) % 3;
            if (occupancy === 2) continue;

            const score =
                (nums[index] & (slot + 1)) +
                dfs(state + powers[slot], index + 1);
            best = Math.max(best, score);
        }

        memo[state] = best;
        return best;
    }

    return dfs(0, 0);
};
