function maximumBinaryString(binary: string): string {
    let firstZero = -1;
    let zeroCount = 0;

    for (let i = 0; i < binary.length; i++) {
        if (binary[i] === "0") {
            if (firstZero === -1) firstZero = i;
            zeroCount++;
        }
    }

    if (zeroCount <= 1) return binary;

    const zeroPosition = firstZero + zeroCount - 1;
    return (
        "1".repeat(zeroPosition) +
        "0" +
        "1".repeat(binary.length - zeroPosition - 1)
    );
};
