function maxCompatibilitySum(students: number[][], mentors: number[][]): number {
    const m = students.length;
    const n = students[0].length;
    const scores: number[][] = Array.from(
        { length: m },
        () => new Array<number>(m).fill(0)
    );

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < m; j++) {
            for (let k = 0; k < n; k++) {
                if (students[i][k] === mentors[j][k]) {
                    scores[i][j]++;
                }
            }
        }
    }

    const size = 1 << m;
    const counts = new Uint8Array(size);
    for (let mask = 1; mask < size; mask++) {
        counts[mask] = counts[mask >> 1] + (mask & 1);
    }

    // dp[mask] assigns the first popcount(mask) students to these mentors.
    const dp = new Array<number>(size).fill(-1);
    dp[0] = 0;

    for (let mask = 0; mask < size - 1; mask++) {
        const student = counts[mask];

        for (let mentor = 0; mentor < m; mentor++) {
            const bit = 1 << mentor;
            if ((mask & bit) !== 0) continue;

            const nextMask = mask | bit;
            dp[nextMask] = Math.max(
                dp[nextMask],
                dp[mask] + scores[student][mentor]
            );
        }
    }

    return dp[size - 1];
};
