function maxEqualFreq(nums: number[]): number {
    const counts = new Int32Array(100001);
    const frequencyCounts = new Int32Array(nums.length + 1);
    let maxFrequency = 0;
    let answer = 0;

    for (let i = 0; i < nums.length; i++) {
        const value = nums[i];
        const oldFrequency = counts[value];

        if (oldFrequency > 0) {
            frequencyCounts[oldFrequency]--;
        }

        const newFrequency = oldFrequency + 1;
        counts[value] = newFrequency;
        frequencyCounts[newFrequency]++;
        maxFrequency = Math.max(maxFrequency, newFrequency);

        const length = i + 1;

        const allUnique = maxFrequency === 1;

        const removeSingleton =
            frequencyCounts[1] === 1 &&
            maxFrequency * frequencyCounts[maxFrequency] + 1 === length;

        const reduceLargest =
            frequencyCounts[maxFrequency] === 1 &&
            maxFrequency +
                (maxFrequency - 1) * frequencyCounts[maxFrequency - 1] ===
                length;

        if (allUnique || removeSingleton || reduceLargest) {
            answer = length;
        }
    }

    return answer;
};
