function maximumBeauty(flowers: number[], newFlowers: number, target: number, full: number, partial: number): number {
    flowers.sort((a, b) => a - b);

    const n = flowers.length;
    let incomplete = n;
    while (incomplete > 0 && flowers[incomplete - 1] >= target) {
        incomplete--;
    }

    const prefix = new Array<number>(incomplete + 1).fill(0);
    for (let i = 0; i < incomplete; i++) {
        prefix[i + 1] = prefix[i] + flowers[i];
    }

    let remaining = newFlowers;
    let answer = 0;

    // Complete the largest incomplete gardens first.
    for (let count = incomplete; count >= 0; count--) {
        if (remaining < 0) break;

        if (count === 0) {
            answer = Math.max(answer, n * full);
            break;
        }

        // Find the largest prefix that can be raised to its largest value.
        let low = 1;
        let high = count;
        while (low < high) {
            const mid = Math.floor((low + high + 1) / 2);
            const cost = flowers[mid - 1] * mid - prefix[mid];

            if (cost <= remaining) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }

        const minimum = Math.min(
            target - 1,
            Math.floor((remaining + prefix[low]) / low)
        );

        answer = Math.max(
            answer,
            (n - count) * full + minimum * partial
        );

        remaining -= target - flowers[count - 1];
    }

    return answer;
};
