function minDays(n: number): number {
    const memo = new Map<number, number>();

    function solve(oranges: number): number {
        if (oranges <= 1) return oranges;

        const cached = memo.get(oranges);
        if (cached !== undefined) return cached;

        const days = 1 + Math.min(
            oranges % 2 + solve(Math.floor(oranges / 2)),
            oranges % 3 + solve(Math.floor(oranges / 3))
        );

        memo.set(oranges, days);
        return days;
    }

    return solve(n);
};
