function minDays(bloomDay: number[], m: number, k: number): number {
    if (m * k > bloomDay.length) {
        return -1;
    }

    let left = bloomDay[0];
    let right = bloomDay[0];

    for (const day of bloomDay) {
        left = Math.min(left, day);
        right = Math.max(right, day);
    }

    while (left < right) {
        const mid = left + Math.floor((right - left) / 2);
        let bouquets = 0;
        let consecutive = 0;

        for (const day of bloomDay) {
            if (day > mid) {
                consecutive = 0;
            } else {
                consecutive++;
                if (consecutive === k) {
                    bouquets++;
                    consecutive = 0;
                    if (bouquets === m) {
                        break;
                    }
                }
            }
        }

        if (bouquets >= m) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }

    return left;
};
