function minSessions(tasks: number[], sessionTime: number): number {
    const n = tasks.length;
    const size = 1 << n;
    const sessions = new Int32Array(size);
    const usedTime = new Int32Array(size);

    sessions.fill(n + 1);
    sessions[0] = 1;

    for (let mask = 1; mask < size; mask++) {
        for (let i = 0; i < n; i++) {
            const bit = 1 << i;
            if ((mask & bit) === 0) continue;

            const previous = mask ^ bit;
            let nextSessions = sessions[previous];
            let nextTime = usedTime[previous] + tasks[i];

            if (nextTime > sessionTime) {
                nextSessions++;
                nextTime = tasks[i];
            }

            if (
                nextSessions < sessions[mask] ||
                (nextSessions === sessions[mask] && nextTime < usedTime[mask])
            ) {
                sessions[mask] = nextSessions;
                usedTime[mask] = nextTime;
            }
        }
    }

    return sessions[size - 1];
};
