function maxSizeSlices(slices: number[]): number {
    const count = slices.length / 3;

    const solveLinear = (start: number, end: number): number => {
        let prevTwo = new Array<number>(count + 1).fill(-Infinity);
        let prevOne = new Array<number>(count + 1).fill(-Infinity);
        prevTwo[0] = prevOne[0] = 0;

        for (let i = start; i < end; i++) {
            const current = new Array<number>(count + 1).fill(-Infinity);
            current[0] = 0;

            for (let chosen = 1; chosen <= count; chosen++) {
                current[chosen] = Math.max(
                    prevOne[chosen],
                    prevTwo[chosen - 1] + slices[i]
                );
            }

            prevTwo = prevOne;
            prevOne = current;
        }

        return prevOne[count];
    };

    // The first and last slices cannot both be chosen.
    return Math.max(
        solveLinear(0, slices.length - 1),
        solveLinear(1, slices.length)
    );
};
