function isScramble(s1: string, s2: string): boolean {
    if (s1.length !== s2.length) return false;
    if (s1 === s2) return true;

    const n = s1.length;
    const memo = new Int8Array((n + 1) * n * n);
    const chars1 = Array.from(s1, c => c.charCodeAt(0) - 97);
    const chars2 = Array.from(s2, c => c.charCodeAt(0) - 97);

    const dfs = (i: number, j: number, length: number): boolean => {
        const key = (length * n + i) * n + j;
        if (memo[key] !== 0) return memo[key] === 1;

        const counts = new Int32Array(26);
        let identical = true;

        for (let k = 0; k < length; k++) {
            const a = chars1[i + k];
            const b = chars2[j + k];
            counts[a]++;
            counts[b]--;
            if (a !== b) identical = false;
        }

        if (identical) {
            memo[key] = 1;
            return true;
        }

        for (let c = 0; c < 26; c++) {
            if (counts[c] !== 0) {
                memo[key] = -1;
                return false;
            }
        }

        for (let split = 1; split < length; split++) {
            const remaining = length - split;

            if (
                (dfs(i, j, split) &&
                    dfs(i + split, j + split, remaining)) ||
                (dfs(i, j + remaining, split) &&
                    dfs(i + split, j, remaining))
            ) {
                memo[key] = 1;
                return true;
            }
        }

        memo[key] = -1;
        return false;
    };

    return dfs(0, 0, n);
};
