function medianSlidingWindow(nums: number[], k: number): number[] {
    // Coordinate compression preserves numeric ordering.
    const values = Array.from(new Set(nums)).sort((a, b) => a - b);
    const ranks = new Map<number, number>();
    for (let i = 0; i < values.length; i++) {
        ranks.set(values[i], i + 1);
    }

    const size = values.length;
    const tree = new Int32Array(size + 1);

    function update(index: number, delta: number): void {
        while (index <= size) {
            tree[index] += delta;
            index += index & -index;
        }
    }

    let highestBit = 1;
    while (highestBit * 2 <= size) {
        highestBit *= 2;
    }

    // Find the value at the given 1-based position in the current window.
    function select(order: number): number {
        let index = 0;
        for (let bit = highestBit; bit > 0; bit = Math.floor(bit / 2)) {
            const next = index + bit;
            if (next <= size && tree[next] < order) {
                index = next;
                order -= tree[next];
            }
        }
        return values[index];
    }

    const result: number[] = [];
    const lowerOrder = Math.floor((k + 1) / 2);
    const upperOrder = Math.floor(k / 2) + 1;

    for (let i = 0; i < nums.length; i++) {
        update(ranks.get(nums[i])!, 1);

        if (i >= k) {
            update(ranks.get(nums[i - k])!, -1);
        }

        if (i >= k - 1) {
            const lower = select(lowerOrder);
            result.push(
                k % 2 === 1 ? lower : (lower + select(upperOrder)) / 2
            );
        }
    }

    return result;
};
