function sortByBits(arr: number[]): number[] {
    const bitCounts = new Map<number, number>();

    for (const value of arr) {
        if (bitCounts.has(value)) continue;

        let remaining = value;
        let count = 0;

        while (remaining !== 0) {
            remaining &= remaining - 1;
            count++;
        }

        bitCounts.set(value, count);
    }

    return arr.sort((a, b) => {
        const difference = bitCounts.get(a)! - bitCounts.get(b)!;
        return difference || a - b;
    });
