function minStickers(stickers: string[], target: string): number {
    const m = target.length;
    const letters = Array.from(target, ch => ch.charCodeAt(0) - 97);
    const candidates: number[][][] = Array.from({ length: 26 }, () => []);

    for (const sticker of stickers) {
        const counts = new Array<number>(26).fill(0);
        for (const ch of sticker) {
            counts[ch.charCodeAt(0) - 97]++;
        }

        for (let c = 0; c < 26; c++) {
            if (counts[c] > 0) {
                candidates[c].push(counts);
            }
        }
    }

    for (const c of letters) {
        if (candidates[c].length === 0) return -1;
    }

    const fullMask = (1 << m) - 1;
    const memo = new Int32Array(1 << m);
    memo.fill(-2);
    memo[fullMask] = 0;

    function dfs(mask: number): number {
        if (memo[mask] !== -2) return memo[mask];

        let first = 0;
        while ((mask & (1 << first)) !== 0) first++;

        let best = Infinity;

        // Some sticker must cover the first missing letter.
        for (const counts of candidates[letters[first]]) {
            const available = counts.slice();
            let nextMask = mask;

            for (let i = 0; i < m; i++) {
                const c = letters[i];
                if ((nextMask & (1 << i)) === 0 && available[c] > 0) {
                    available[c]--;
                    nextMask |= 1 << i;
                }
            }

            const remaining = dfs(nextMask);
            if (remaining !== -1) {
                best = Math.min(best, remaining + 1);
                if (best === 1) break;
            }
        }

        memo[mask] = best === Infinity ? -1 : best;
        return memo[mask];
    }

    return dfs(0);
};
