function strWithout3a3b(a: number, b: number): string {
    const result: string[] = [];

    while (a > 0 || b > 0) {
        const n = result.length;
        let useA = a >= b;

        if (n >= 2 && result[n - 1] === result[n - 2]) {
            useA = result[n - 1] === "b";
        }

        if (useA) {
            result.push("a");
            a--;
        } else {
            result.push("b");
            b--;
        }
    }

    return result.join("");
};
