function sumOddLengthSubarrays(arr: number[]): number {
    let sum = 0;
    const n = arr.length;

    for (let i = 0; i < n; i++) {
        const containingSubarrays = (i + 1) * (n - i);
        const oddLengthSubarrays = Math.floor((containingSubarrays + 1) / 2);
        sum += arr[i] * oddLengthSubarrays;
    }

    return sum;
};
