function kWeakestRows(mat: number[][], k: number): number[] {
    const rows: { index: number; soldiers: number }[] = [];

    for (let i = 0; i < mat.length; i++) {
        let left = 0;
        let right = mat[i].length;

        while (left < right) {
            const mid = left + Math.floor((right - left) / 2);
            if (mat[i][mid] === 1) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        rows.push({ index: i, soldiers: left });
    }

    rows.sort((a, b) => a.soldiers - b.soldiers || a.index - b.index);

    return rows.slice(0, k).map(row => row.index);
};
