function uncommonFromSentences(s1: string, s2: string): string[] {
    const counts = new Map<string, number>();

    for (const word of `${s1} ${s2}`.split(" ")) {
        counts.set(word, (counts.get(word) ?? 0) + 1);
    }

    const result: string[] = [];
    for (const [word, count] of counts) {
        if (count === 1) {
            result.push(word);
        }
    }

    return result;
};
