function isSolvable(words: string[], result: string): boolean {
    const length = result.length;
    const columns: number[][] = Array.from({ length }, () => []);
    const leading = new Uint8Array(26);
    const digits = new Int8Array(26).fill(-1);

    let maxWordLength = 0;

    for (const word of words) {
        if (word.length > length) return false;
        maxWordLength = Math.max(maxWordLength, word.length);

        if (word.length > 1) {
            leading[word.charCodeAt(0) - 65] = 1;
        }

        for (let column = 0; column < word.length; column++) {
            columns[column].push(word.charCodeAt(word.length - 1 - column) - 65);
        }
    }

    if (length > maxWordLength + 1) return false;

    if (length > 1) {
        leading[result.charCodeAt(0) - 65] = 1;
    }

    const resultLetters = Array.from(
        { length },
        (_, column) => result.charCodeAt(length - 1 - column) - 65
    );

    function search(
        column: number,
        row: number,
        sum: number,
        used: number
    ): boolean {
        if (column === length) return sum === 0;

        if (row === columns[column].length) {
            const letter = resultLetters[column];
            const digit = sum % 10;
            const carry = Math.floor(sum / 10);

            if (digits[letter] !== -1) {
                return digits[letter] === digit &&
                    search(column + 1, 0, carry, used);
            }

            const bit = 1 << digit;
            if ((used & bit) !== 0 || (digit === 0 && leading[letter])) {
                return false;
            }

            digits[letter] = digit;
            if (search(column + 1, 0, carry, used | bit)) return true;
            digits[letter] = -1;
            return false;
        }

        const letter = columns[column][row];

        if (digits[letter] !== -1) {
            return search(column, row + 1, sum + digits[letter], used);
        }

        for (let digit = leading[letter] ? 1 : 0; digit <= 9; digit++) {
            const bit = 1 << digit;
            if ((used & bit) !== 0) continue;

            digits[letter] = digit;
            if (search(column, row + 1, sum + digit, used | bit)) return true;
            digits[letter] = -1;
        }

        return false;
    }

    return search(0, 0, 0, 0);
};
